    sorted_jobs = sorted(range(n), key=lambda x: totals[x], reverse=True)
    if n <= 8:
        min_makespan = float('inf')
        best_seq = list(range(1, n + 1))
        for perm in itertools.permutations(sorted_jobs):
            seq = [p + 1 for p in perm]
            C = [[0] * m for _ in range(n)]
            for j in range(n):
                for i in range(m):
                    if j == 0:
                        C[j][i] = matrix[perm[j]][i]
                    else:
                        C[j][i] = matrix[perm[j]][i] + max(C[j - 1][i], C[j][i - 1] if i > 0 else 0)
            makespan = C[n - 1][m - 1]
            if makespan < min_makespan:
                min_makespan = makespan
                best_seq = seq
        return {'job_sequence': best_seq}
    else:
        # Simple heuristic for large n: sort by total processing time
        return {'job_sequence': [j + 1 for j in sorted_jobs]}
